package app.truemotion.vector;
import java.util.*;
/** Resolution-independent planar arrangement of cubic vector strokes. */
public final class VectorFaces {
 static final double EPS=1e-6,FLAT=.18;
 static final class Curve {double[] p;double width;int owner;Curve(double[] p,double w,int o){this.p=p;width=w;owner=o;}double[] at(double t){double q=1-t;return new double[]{q*q*q*p[0]+3*q*q*t*p[2]+3*q*t*t*p[4]+t*t*t*p[6],q*q*q*p[1]+3*q*q*t*p[3]+3*q*t*t*p[5]+t*t*t*p[7]};}double[] derivative(double t){double q=1-t;return new double[]{3*q*q*(p[2]-p[0])+6*q*t*(p[4]-p[2])+3*t*t*(p[6]-p[4]),3*q*q*(p[3]-p[1])+6*q*t*(p[5]-p[3])+3*t*t*(p[7]-p[5])};}}
 static final class Seg {Curve c;double t0,t1;double[] a,b;TreeSet<Double> cuts=new TreeSet<Double>();Seg(Curve c,double t0,double t1){this.c=c;this.t0=t0;this.t1=t1;a=c.at(t0);b=c.at(t1);cuts.add(0d);cuts.add(1d);}}
 static final class Vertex {double x,y;int component=-1;ArrayList<Edge> out=new ArrayList<Edge>();Vertex(double x,double y){this.x=x;this.y=y;}}
 static final class Edge {Vertex a,b;Curve c;double ta,tb;Edge reverse,next;boolean seen;Edge(Vertex a,Vertex b,Curve c,double ta,double tb){this.a=a;this.b=b;this.c=c;this.ta=ta;this.tb=tb;}}
 static final class Face {ArrayList<VectorDocument.Node> nodes=new ArrayList<VectorDocument.Node>();double area;int component;}
 static double cross(double ax,double ay,double bx,double by){return ax*by-ay*bx;}
 static double lineDistance(double[] p,double[] a,double[] b){double dx=b[0]-a[0],dy=b[1]-a[1],l=Math.hypot(dx,dy);return l<EPS?Math.hypot(p[0]-a[0],p[1]-a[1]):Math.abs(cross(dx,dy,p[0]-a[0],p[1]-a[1]))/l;}
 static void flatten(Curve c,double lo,double hi,List<Seg> out,int depth){double[] a=c.at(lo),b=c.at(hi);double m=(lo+hi)/2;double error=Math.max(lineDistance(c.at((3*lo+hi)/4),a,b),Math.max(lineDistance(c.at(m),a,b),lineDistance(c.at((lo+3*hi)/4),a,b)));if(depth<14&&(error>FLAT||Math.hypot(b[0]-a[0],b[1]-a[1])>96)){flatten(c,lo,m,out,depth+1);flatten(c,m,hi,out,depth+1);}else if(Math.hypot(b[0]-a[0],b[1]-a[1])>EPS)out.add(new Seg(c,lo,hi));if(out.size()>12000)throw new IllegalArgumentException("Vector fill has too many segments");}
 static double[] world(VectorDocument.Shape s,double x,double y){return s.world(x,y);}
 static void contour(VectorDocument.Shape shape,List<VectorDocument.Node> nodes,boolean closed,int owner,List<Seg> out,List<double[]> ends){if(nodes.size()<2)return;int n=closed?nodes.size():nodes.size()-1;double width=shape.strokeWidth*Math.max(Math.abs(shape.sx),Math.abs(shape.sy));for(int i=0;i<n;i++){VectorDocument.Node a=nodes.get(i),b=nodes.get((i+1)%nodes.size());double[] p=world(shape,a.x,a.y),q=world(shape,a.x+a.ox,a.y+a.oy),r=world(shape,b.x+b.ix,b.y+b.iy),v=world(shape,b.x,b.y);Curve c=new Curve(new double[]{p[0],p[1],q[0],q[1],r[0],r[1],v[0],v[1]},width,owner);flatten(c,0,1,out,0);}if(!closed){double[] a=world(shape,nodes.get(0).x,nodes.get(0).y),b=world(shape,nodes.get(nodes.size()-1).x,nodes.get(nodes.size()-1).y);ends.add(new double[]{a[0],a[1],width,owner});ends.add(new double[]{b[0],b[1],width,owner});}}
 static Seg connector(double[] a,double[] b){return new Seg(new Curve(new double[]{a[0],a[1],a[0],a[1],b[0],b[1],b[0],b[1]},0,-1),0,1);}
 static void closeVisibleJoins(List<Seg> lines,List<double[]> ends){ArrayList<Seg> bridges=new ArrayList<Seg>();for(double[] e:ends){double best=Double.POSITIVE_INFINITY;Seg target=null;double t=0;for(Seg s:lines){double dx=s.b[0]-s.a[0],dy=s.b[1]-s.a[1],l=dx*dx+dy*dy;if(l<EPS)continue;if(Math.hypot(e[0]-s.a[0],e[1]-s.a[1])<EPS||Math.hypot(e[0]-s.b[0],e[1]-s.b[1])<EPS)continue;double f=Math.max(0,Math.min(1,((e[0]-s.a[0])*dx+(e[1]-s.a[1])*dy)/l)),d=Math.hypot(e[0]-s.a[0]-f*dx,e[1]-s.a[1]-f*dy),tolerance=Math.max(.2,(e[2]+s.c.width)/2);if(d>tolerance||d<.01||s.c.owner==(int)e[3]&&d<e[2]*.6&&f>EPS&&f<1-EPS)continue;if(d<best){best=d;target=s;t=f;}}if(target!=null){target.cuts.add(t);double[] q={target.a[0]+(target.b[0]-target.a[0])*t,target.a[1]+(target.b[1]-target.a[1])*t};bridges.add(connector(e,q));}}lines.addAll(bridges);}
 static void intersect(Seg a,Seg b){double ax=a.b[0]-a.a[0],ay=a.b[1]-a.a[1],bx=b.b[0]-b.a[0],by=b.b[1]-b.a[1],den=cross(ax,ay,bx,by),dx=b.a[0]-a.a[0],dy=b.a[1]-a.a[1];if(Math.abs(den)<EPS){if(Math.abs(cross(dx,dy,ax,ay))>EPS)return;for(double[] p:new double[][]{b.a,b.b}){double t=(Math.abs(ax)>Math.abs(ay)?(p[0]-a.a[0])/ax:(p[1]-a.a[1])/ay);if(t>EPS&&t<1-EPS)a.cuts.add(t);}for(double[] p:new double[][]{a.a,a.b}){double t=(Math.abs(bx)>Math.abs(by)?(p[0]-b.a[0])/bx:(p[1]-b.a[1])/by);if(t>EPS&&t<1-EPS)b.cuts.add(t);}return;}double t=cross(dx,dy,bx,by)/den,u=cross(dx,dy,ax,ay)/den;if(t>=-EPS&&t<=1+EPS&&u>=-EPS&&u<=1+EPS){a.cuts.add(Math.max(0,Math.min(1,t)));b.cuts.add(Math.max(0,Math.min(1,u)));}}
 static Vertex vertex(Map<String,Vertex> map,double x,double y){String key=Math.round(x/EPS)+":"+Math.round(y/EPS);Vertex v=map.get(key);if(v==null){v=new Vertex(x,y);map.put(key,v);}return v;}
 static void intersections(List<Seg> lines){HashMap<Long,ArrayList<Integer>> grid=new HashMap<Long,ArrayList<Integer>>();HashSet<Long> checked=new HashSet<Long>();for(int i=0;i<lines.size();i++){Seg s=lines.get(i);int x0=(int)Math.floor(Math.min(s.a[0],s.b[0])/96),x1=(int)Math.floor(Math.max(s.a[0],s.b[0])/96),y0=(int)Math.floor(Math.min(s.a[1],s.b[1])/96),y1=(int)Math.floor(Math.max(s.a[1],s.b[1])/96);for(int y=y0;y<=y1;y++)for(int x=x0;x<=x1;x++){long cell=((long)x<<32)^(y&0xffffffffL);ArrayList<Integer> bucket=grid.get(cell);if(bucket==null){bucket=new ArrayList<Integer>();grid.put(cell,bucket);}for(int j:bucket){long pair=((long)j<<32)|(i&0xffffffffL);if(checked.add(pair)){if(checked.size()>2000000)throw new IllegalArgumentException("Vector fill has too many intersections");intersect(lines.get(j),s);}}bucket.add(i);}}}
 static boolean contains(List<VectorDocument.Node> points,double x,double y){boolean in=false;for(int i=0,j=points.size()-1;i<points.size();j=i++){VectorDocument.Node a=points.get(i),b=points.get(j);if((a.y>y)!=(b.y>y)&&x<(b.x-a.x)*(y-a.y)/(b.y-a.y)+a.x)in=!in;}return in;}
 public static VectorDocument.Shape fill(List<VectorDocument.Shape> shapes,double x,double y,int color){ArrayList<Seg> lines=new ArrayList<Seg>();ArrayList<double[]> ends=new ArrayList<double[]>();int owner=0;for(VectorDocument.Shape s:shapes){if(s.bucketFill||s.opacity<=0||s.isImage()||s.isText()||s.isSymbol()||((s.stroke>>>24)==0&&(!s.closed||(s.fill>>>24)==0)))continue;contour(s,s.nodes,s.closed,++owner,lines,ends);for(List<VectorDocument.Node> c:s.contours)contour(s,c,true,owner,lines,ends);}if(lines.isEmpty())return null;closeVisibleJoins(lines,ends);intersections(lines);
  HashMap<String,Vertex> vertices=new HashMap<String,Vertex>();ArrayList<Edge> edges=new ArrayList<Edge>();HashSet<String> unique=new HashSet<String>();for(Seg s:lines){Double previous=null;for(double t:s.cuts){if(previous!=null&&t-previous>EPS){double p=previous,q=t;Vertex a=vertex(vertices,s.a[0]+(s.b[0]-s.a[0])*p,s.a[1]+(s.b[1]-s.a[1])*p),b=vertex(vertices,s.a[0]+(s.b[0]-s.a[0])*q,s.a[1]+(s.b[1]-s.a[1])*q);String id=Math.round(a.x/EPS)+":"+Math.round(a.y/EPS)+":"+Math.round(b.x/EPS)+":"+Math.round(b.y/EPS),rev=Math.round(b.x/EPS)+":"+Math.round(b.y/EPS)+":"+Math.round(a.x/EPS)+":"+Math.round(a.y/EPS);if(a!=b&&!unique.contains(rev)&&unique.add(id)){Edge e=new Edge(a,b,s.c,s.t0+(s.t1-s.t0)*p,s.t0+(s.t1-s.t0)*q),r=new Edge(b,a,s.c,e.tb,e.ta);e.reverse=r;r.reverse=e;a.out.add(e);b.out.add(r);edges.add(e);edges.add(r);}}previous=t;}}
  for(Vertex v:vertices.values())v.out.sort((a,b)->Double.compare(Math.atan2(a.b.y-v.y,a.b.x-v.x),Math.atan2(b.b.y-v.y,b.b.x-v.x)));for(Edge e:edges){List<Edge> out=e.b.out;int index=out.indexOf(e.reverse);e.next=out.get((index+out.size()-1)%out.size());}
  int component=0;for(Vertex v:vertices.values())if(v.component<0){ArrayDeque<Vertex> queue=new ArrayDeque<Vertex>();queue.add(v);v.component=component;while(!queue.isEmpty()){Vertex u=queue.removeFirst();for(Edge e:u.out)if(e.b.component<0){e.b.component=component;queue.add(e.b);}}component++;}
  ArrayList<Face> faces=new ArrayList<Face>();for(Edge first:edges)if(!first.seen){Face face=new Face();face.component=first.a.component;Edge e=first;do{e.seen=true;VectorDocument.Node n=new VectorDocument.Node(e.a.x,e.a.y);double[] d=e.c.derivative(e.ta);double span=(e.tb-e.ta)/3;n.ox=d[0]*span;n.oy=d[1]*span;d=e.c.derivative(e.tb);VectorDocument.Node end=new VectorDocument.Node(e.b.x,e.b.y);end.ix=-d[0]*span;end.iy=-d[1]*span;if(!face.nodes.isEmpty()){VectorDocument.Node prior=face.nodes.get(face.nodes.size()-1);prior.ox=n.ox;prior.oy=n.oy;}else face.nodes.add(n);face.nodes.add(end);face.area+=cross(e.a.x-first.a.x,e.a.y-first.a.y,e.b.x-first.a.x,e.b.y-first.a.y);e=e.next;if(face.nodes.size()>edges.size()+1)throw new IllegalArgumentException("Invalid vector face");}while(e!=first&&!e.seen);if(e==first&&face.nodes.size()>3){VectorDocument.Node last=face.nodes.remove(face.nodes.size()-1),n=face.nodes.get(0);n.ix=last.ix;n.iy=last.iy;face.area/=2;if(face.area>EPS)faces.add(face);}}
  Face best=null;for(Face f:faces)if(contains(f.nodes,x,y)&&(best==null||f.area<best.area))best=f;if(best==null)return null;VectorDocument.Shape result=new VectorDocument.Shape();result.closed=true;result.bucketFill=true;result.strokeWidth=0;result.fill=color;result.nodes.addAll(best.nodes);
  ArrayList<Face> holes=new ArrayList<Face>();for(Face f:faces)if(f!=best&&f.component!=best.component&&f.area<best.area&&contains(best.nodes,f.nodes.get(0).x,f.nodes.get(0).y)&&!contains(f.nodes,x,y))holes.add(f);holes.sort((a,b)->Double.compare(b.area,a.area));for(Face f:holes){boolean nested=false;for(List<VectorDocument.Node> c:result.contours)if(contains(c,f.nodes.get(0).x,f.nodes.get(0).y))nested=true;if(nested)continue;ArrayList<VectorDocument.Node> reverse=new ArrayList<VectorDocument.Node>();for(int i=f.nodes.size()-1;i>=0;i--){VectorDocument.Node n=f.nodes.get(i).copy();double ix=n.ix,iy=n.iy;n.ix=n.ox;n.iy=n.oy;n.ox=ix;n.oy=iy;reverse.add(n);}result.contours.add(reverse);}result.recenter();return result;
 }
}
